"validated":true,"deferrable":false,"definition":"FOREIGN KEY (competition_id) REFERENCES competitions(id)"},{"rel":"private_baden_history.club_bindings","parent":"teams","deferred":false,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (team_id) REFERENCES teams(id)"},{"rel":"private_fcf_g1_supplement.markers","parent":"matches","deferred":false,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (match_id) REFERENCES matches(id)"},{"rel":"private_fcf_g1_supplement.markers","parent":"rounds","deferred":false,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (round_id) REFERENCES rounds(id)"},{"rel":"private_fcf_g1_supplement.markers","parent":"teams","deferred":false,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (home_team_id) REFERENCES teams(id)"},{"rel":"private_fcf_g1_supplement.markers","parent":"teams","deferred":false,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (away_team_id) REFERENCES teams(id)"},{"rel":"private_fcf_g1_supplement.receipts","parent":"private_fcf_g1_supplement.markers","deferred":false,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (match_id) REFERENCES private_fcf_g1_supplement.markers(match_id)"},{"rel":"private_baden_transition.versions","parent":"competitions","deferred":false,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (competition_id) REFERENCES competitions(id)"},{"rel":"private_baden_transition.versions","parent":"rounds","deferred":false,"validated":true,"deferrable":false,"definition":"FOREIGN KEY (opening_round_id) REFERENCES rounds(id)"}]';q record;actual_shape jsonb;catalog jsonb;rows jsonb;n bigint;pids bigint[];rids bigint[];mids bigint[];ftids bigint[];tids bigint[];goalrefs jsonb:='[]';begin
 select jsonb_agg(j order by j->>'rel',j->>'definition')into expected_fk from jsonb_array_elements(expected_fk)j;
 -- Both event tables are either the exact reviewed Scout delta or absent.
 perform private_fcf_six_target_release.require((to_regclass('scout.dogodki')is null)=(to_regclass('scout.prisotnost')is null),'incomplete Scout event schema');
 if to_regclass('scout.dogodki')is null then
  registry:=registry-'scout.dogodki'-'scout.prisotnost';shapes:=shapes-'scout.dogodki'-'scout.prisotnost';
  registry:=jsonb_set(registry,array['scout.dnevnik','where'],to_jsonb(replace(registry#>>'{scout.dnevnik,where}', ' or x.parametri->>''dogodek'' in(select id::text from scout.dogodki where competition_id= $9)','')));
  select coalesce(jsonb_agg(j),'[]')into expected_fk from jsonb_array_elements(expected_fk)j where j->>'rel'not in('scout.dogodki','scout.prisotnost');
 end if;
 -- Close every relevant FK and every reviewed relation's complete column/type
 -- shape. This check runs even on empty tables. No row-count inference of coverage.
 select coalesce(jsonb_agg(jsonb_build_object('rel',c.conrelid::regclass::text,'parent',c.confrelid::regclass::text,'definition',pg_get_constraintdef(c.oid),'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred)order by c.conrelid::regclass::text,pg_get_constraintdef(c.oid)),'[]'::jsonb) from pg_constraint c where c.contype='f' and (c.conrelid in(select to_regclass(key)from jsonb_each(shapes))or c.confrelid in('private_fcf_g1_9410.markers'::regclass,'private_fcf_g1_9410.receipts'::regclass,'private_baden_transition.versions'::regclass)or c.confrelid in(select oid from pg_class where relnamespace in('public'::regnamespace,'scout'::regnamespace,'private_fussball'::regnamespace)and relname in('competitions','rounds','teams','players','matches','appearances','goals','fantasy_teams','mini_lige','zahtevki_igralca','preverjeni_racuni','uradne_odsotnosti','player_scores','statistika_igralcev','tocke_krogov','dogodki','card_reports','card_events'))) into catalog;
 perform private_fcf_six_target_release.require(catalog=expected_fk,'unknown/missing relevant FK definition, validation or deferrability');
 for q in select key,value from jsonb_each(shapes)order by key loop
  perform private_fcf_six_target_release.require(to_regclass(q.key)is not null,'missing required dependency relation: '||q.key);
  select jsonb_agg(jsonb_build_array(a.attname,a.atttypid::regtype::text)order by a.attnum)into actual_shape from pg_attribute a where a.attrelid=to_regclass(q.key)and a.attnum>0 and not a.attisdropped;
  perform private_fcf_six_target_release.require(actual_shape=q.value,'unreviewed dependency shape: '||q.key);
 end loop;
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_attribute a join pg_class t on t.oid=a.attrelid join pg_namespace ns on ns.oid=t.relnamespace where t.relkind in('r','p')and a.attnum>0 and not a.attisdropped and(ns.nspname in('public','scout')or ns.nspname like 'private\_%'escape '\')and(ns.nspname='scout'or a.attname~'(^|_)(competition|round|match|player|goal|appearance|fantasy_team|dogodek)_id$'or a.attname in('podobni','igralci','tekma_id','gol_strelec_id','asistent_id'))and not shapes ? (ns.nspname||'.'||t.relname)),'unknown relevant non-FK/Scout relation');

select coalesce(array_agg(id),'{}')into pids from players where competition_id=cid;select coalesce(array_agg(id),'{}')into rids from rounds where competition_id=cid;select coalesce(array_agg(id),'{}')into mids from matches where round_id=any(rids);select coalesce(array_agg(id),'{}')into ftids from fantasy_teams where competition_id=cid;select coalesce(array_agg(team_id),'{}')into tids from private_baden_history.club_bindings where competition_id=cid;
for q in select key,value from jsonb_each(registry)where value->'user'='true'::jsonb loop execute format('select count(*)from %s x where %s',q.key,q.value->>'where')into n using pids,rids,mids,ftids,goalrefs,tids,null::bigint,null::bigint,cid;perform private_baden_history.require(n=0,'version target human dependency: '||q.key);end loop;perform private_fcf_six_target_release.no_target_users(cid);end$$;
do $clone$begin if(select encode(sha256(convert_to(prosrc,'UTF8')),'hex')from pg_proc where oid='public.get_fussball_historical_preparation(bigint)'::regprocedure)<>'194da677dfdf566561d4934800e2483d7a6ffb91dd88f4605556c5504a9df50a'then raise exception 'BADEN_VERSION: exact cold predecessor required';end if;end$clone$;
create function private_baden_transition.m1_cold(p_competition_id bigint)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as '
#variable_conflict use_column

declare c competitions;p private_baden_history.prepared;v jsonb;b jsonb;f jsonb;r rounds;m matches;history jsonb;cards jsonb;cold jsonb;opening rounds;
begin
 perform private_fussball.service();select *into c from competitions where id=p_competition_id;
 select *into p from private_baden_history.prepared where competition_id=c.id;select manifest into v from private_baden_history.catalog where manifest_sha256=p.manifest_sha256;
 perform private_baden_history.require(p.competition_id is not null and v is not null and not c.active and c.slug=v->>''slug''and c.source=''fussball-public''and c.source_league_code=v->>''currentCode''and c.source_policy=''fussball-community-cards-v1''and exists(select 1 from countries where id=c.country_id and code=''DE'')and not exists(select 1 from fantasy_teams where competition_id=c.id)and not exists(select 1 from fantasy_lineups l join rounds x on x.id=l.round_id where x.competition_id=c.id),''exact inactive no-user preparation required'');
 -- COLD pre-import boundary only. Later imports/runtime must use a separate
 -- installed-history/cards context; this getter intentionally refuses them.
 select jsonb_build_object(
  ''playerCount'',(select count(*)from players where competition_id=c.id),
  ''importedMatchCount'',(select count(*)from matches x join rounds q on q.id=x.round_id where q.competition_id=c.id and x.imported_at is not null),
  ''appearanceCount'',(select count(*)from appearances x join matches z on z.id=x.match_id join rounds q on q.id=z.round_id where q.competition_id=c.id),
  ''goalCount'',(select count(*)from goals x join matches z on z.id=x.match_id join rounds q on q.id=z.round_id where q.competition_id=c.id),
  ''playerScoreCount'',(select count(*)from player_scores x join rounds q on q.id=x.round_id where q.competition_id=c.id),
  ''roundPointsCount'',(select count(*)from tocke_krogov x join rounds q on q.id=x.round_id where q.competition_id=c.id)
 )into cold;
 perform private_baden_history.require(cold=''{"playerCount":0,"importedMatchCount":0,"appearanceCount":0,"goalCount":0,"playerScoreCount":0,"roundPointsCount":0}''::jsonb,''cold pre-import preparation contains players/imported matches/individual statistics or points'');
 perform private_baden_history.require(private_baden_history.sha(v)=p.manifest_sha256 and (v->>''currentFreshUntil'')::timestamptz>clock_timestamp()and jsonb_array_length(p.bindings)=jsonb_array_length(v->''fixtures''),''compiled manifest/freshness/bindings drift'');
 for b in select value from jsonb_array_elements(p.bindings)loop
  f:=b->''fixture'';select *into r from rounds where id=(b->>''roundId'')::bigint;select *into m from matches where id=(b->>''matchId'')::bigint;
  perform private_baden_history.require(exists(select 1 from jsonb_array_elements(v->''fixtures'')x where x=f)and r.competition_id=c.id and r.season=f->>''season''and r.number=(f->>''round'')::int and m.round_id=r.id and m.home_team_id=(b->>''homeTeamId'')::bigint and m.away_team_id=(b->>''awayTeamId'')::bigint and m.zapisnik_id=f->>''reportId''and m.source_url=f->>''sourceUrl''and m.played_on=(f->>''date'')::date and m.source_round=(f->>''round'')::int and m.source_phase is null
  and exists(select 1 from private_baden_history.club_bindings cb join teams t on t.id=cb.team_id where cb.competition_id=c.id and cb.source_competition_id=f->>''sourceCompetitionId''and cb.season=f->>''season''and cb.source_club_id=f->>''homeSourceClubId''and cb.name=f->>''homeName''and cb.team_id=m.home_team_id and t.country_id=c.country_id and t.name=cb.name)
  and exists(select 1 from private_baden_history.club_bindings cb join teams t on t.id=cb.team_id where cb.competition_id=c.id and cb.source_competition_id=f->>''sourceCompetitionId''and cb.season=f->>''season''and cb.source_club_id=f->>''awaySourceClubId''and cb.name=f->>''awayName''and cb.team_id=m.away_team_id and t.country_id=c.country_id and t.name=cb.name),''actual full source/native fixture binding drift'');
  if(f->>''unavailable'')::boolean then
   perform private_baden_history.require(m.statistics_status=''unavailable_historical''and m.imported_at is null and not m.vir_brez_izida and not m.kontumacija,''immutable marker state drift'');
  end if;
  if f->''score''<>''null''::jsonb then
   perform private_baden_history.require(m.home_goals=(f#>>''{score,domaci}'')::int and m.away_goals=(f#>>''{score,gostje}'')::int,''official score drift'');
  elsif(f->>''unavailable'')::boolean then perform private_baden_history.require(m.home_goals is null and m.away_goals is null,''unknown official result must stay both NULL'');
  else perform private_baden_history.require(m.home_goals=0 and m.away_goals=0 and m.vir_brez_izida and m.imported_at is null,''unplayed header changed'');end if;
 end loop;
 perform private_baden_history.require((select count(*)from matches m join rounds r on r.id=m.round_id where r.competition_id=c.id)=jsonb_array_length(p.bindings),''extra or missing native source fixture'');
 select *into opening from rounds where id=p.opening_round_id;
 perform private_baden_history.require(opening.competition_id=c.id and opening.season=''2026/27''and opening.number=(v->>''openingRound'')::int and c.prvi_fantasy_krog=opening.number and opening.played_on=(v->>''firstFantasyPlayedOn'')::date and opening.lineups_locked_at is null and opening.deadline_at>clock_timestamp(),''future unlocked exact opening required'');
 history:=public.get_installed_historical_statistics_markers(c.id);cards:=public.check_fussball_card_readiness(c.id,v->>''currentCode'');
 perform private_baden_history.require(history->>''policySha256''=private_baden_history.sha(v->''policy'')and history->>''firstFantasyPlayedOn''=v->>''firstFantasyPlayedOn''and cards->>''installed''=''true''and cards->>''enabled''=''true''and cards->>''current_code''=v->>''currentCode''and cards->''archive_codes''=jsonb_build_array(v->>''archiveCode''),''both installed policy readbacks required'');
 return jsonb_build_object(''prepared'',true,''competitionId'',c.id,''active'',false,''noUsers'',true,''coldState'',cold,''sourcePolicy'',c.source_policy,''manifestSha256'',p.manifest_sha256,''bindings'',p.bindings,''bindingSha256'',private_baden_history.sha(p.bindings),''history'',history,''cards'',cards,''policySha256'',history->>''policySha256'',''markerInventorySha256'',private_baden_history.sha(history->''markers''),''firstFantasyPlayedOn'',history->>''firstFantasyPlayedOn'',''openingRoundId'',opening.id);
end';
create function private_baden_transition.m2_cold(p_competition_id bigint)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as '
#variable_conflict use_column

declare c competitions;p private_baden_transition.effective_prepared;v jsonb;b jsonb;f jsonb;r rounds;m matches;history jsonb;cards jsonb;cold jsonb;opening rounds;
begin
 perform private_fussball.service();select *into c from competitions where id=p_competition_id;
 select *into p from private_baden_transition.effective_prepared where competition_id=c.id;select manifest into v from private_baden_transition.effective_catalog where manifest_sha256=p.manifest_sha256;
 perform private_baden_history.require(p.competition_id is not null and v is not null and not c.active and c.slug=v->>''slug''and c.source=''fussball-public''and c.source_league_code=v->>''currentCode''and c.source_policy=''fussball-community-cards-v1''and exists(select 1 from countries where id=c.country_id and code=''DE'')and not exists(select 1 from fantasy_teams where competition_id=c.id)and not exists(select 1 from fantasy_lineups l join rounds x on x.id=l.round_id where x.competition_id=c.id),''exact inactive no-user preparation required'');
 -- COLD pre-import boundary only. Later imports/runtime must use a separate
 -- installed-history/cards context; this getter intentionally refuses them.
 select jsonb_build_object(
  ''playerCount'',(select count(*)from players where competition_id=c.id),
  ''importedMatchCount'',(select count(*)from matches x join rounds q on q.id=x.round_id where q.competition_id=c.id and x.imported_at is not null),
  ''appearanceCount'',(select count(*)from appearances x join matches z on z.id=x.match_id join rounds q on q.id=z.round_id where q.competition_id=c.id),
  ''goalCount'',(select count(*)from goals x join matches z on z.id=x.match_id join rounds q on q.id=z.round_id where q.competition_id=c.id),
  ''playerScoreCount'',(select count(*)from player_scores x join rounds q on q.id=x.round_id where q.competition_id=c.id),
  ''roundPointsCount'',(select count(*)from tocke_krogov x join rounds q on q.id=x.round_id where q.competition_id=c.id)
 )into cold;
 perform private_baden_history.require(cold=''{"playerCount":0,"importedMatchCount":0,"appearanceCount":0,"goalCount":0,"playerScoreCount":0,"roundPointsCount":0}''::jsonb,''cold pre-import preparation contains players/imported matches/individual statistics or points'');
 perform private_baden_history.require(private_baden_history.sha(v)=p.manifest_sha256 and (v->>''currentFreshUntil'')::timestamptz>clock_timestamp()and jsonb_array_length(p.bindings)=jsonb_array_length(v->''fixtures''),''compiled manifest/freshness/bindings drift'');
 for b in select value from jsonb_array_elements(p.bindings)loop
  f:=b->''fixture'';select *into r from rounds where id=(b->>''roundId'')::bigint;select *into m from matches where id=(b->>''matchId'')::bigint;
  perform private_baden_history.require(exists(select 1 from jsonb_array_elements(v->''fixtures'')x where x=f)and r.competition_id=c.id and r.season=f->>''season''and r.number=(f->>''round'')::int and m.round_id=r.id and m.home_team_id=(b->>''homeTeamId'')::bigint and m.away_team_id=(b->>''awayTeamId'')::bigint and m.zapisnik_id=f->>''reportId''and m.source_url=f->>''sourceUrl''and m.played_on=(f->>''date'')::date and m.source_round=(f->>''round'')::int and m.source_phase is null
  and exists(select 1 from private_baden_history.club_bindings cb join teams t on t.id=cb.team_id where cb.competition_id=c.id and cb.source_competition_id=f->>''sourceCompetitionId''and cb.season=f->>''season''and cb.source_club_id=f->>''homeSourceClubId''and cb.name=f->>''homeName''and cb.team_id=m.home_team_id and t.country_id=c.country_id and t.name=cb.name)
  and exists(select 1 from private_baden_history.club_bindings cb join teams t on t.id=cb.team_id where cb.competition_id=c.id and cb.source_competition_id=f->>''sourceCompetitionId''and cb.season=f->>''season''and cb.source_club_id=f->>''awaySourceClubId''and cb.name=f->>''awayName''and cb.team_id=m.away_team_id and t.country_id=c.country_id and t.name=cb.name),''actual full source/native fixture binding drift'');
  if(f->>''unavailable'')::boolean then
   perform private_baden_history.require(m.statistics_status=''unavailable_historical''and m.imported_at is null and not m.vir_brez_izida and not m.kontumacija,''immutable marker state drift'');
  end if;
  if f->''score''<>''null''::jsonb then
   perform private_baden_history.require(m.home_goals=(f#>>''{score,domaci}'')::int and m.away_goals=(f#>>''{score,gostje}'')::int,''official score drift'');
  elsif(f->>''unavailable'')::boolean then perform private_baden_history.require(m.home_goals is null and m.away_goals is null,''unknown official result must stay both NULL'');
  else perform private_baden_history.require(m.home_goals=0 and m.away_goals=0 and m.vir_brez_izida and m.imported_at is null,''unplayed header changed'');end if;
 end loop;
 perform private_baden_history.require((select count(*)from matches m join rounds r on r.id=m.round_id where r.competition_id=c.id)=jsonb_array_length(p.bindings),''extra or missing native source fixture'');
 select *into opening from rounds where id=p.opening_round_id;
 perform private_baden_history.require(opening.competition_id=c.id and opening.season=''2026/27''and opening.number=(v->>''openingRound'')::int and c.prvi_fantasy_krog=opening.number and opening.played_on=(v->>''firstFantasyPlayedOn'')::date and opening.lineups_locked_at is null and opening.deadline_at>clock_timestamp(),''future unlocked exact opening required'');
 history:=public.get_installed_historical_statistics_markers(c.id);cards:=public.check_fussball_card_readiness(c.id,v->>''currentCode'');
 perform private_baden_history.require(history->>''policySha256''=private_baden_history.sha(v->''policy'')and history->>''firstFantasyPlayedOn''=v->>''firstFantasyPlayedOn''and cards->>''installed''=''true''and cards->>''enabled''=''true''and cards->>''current_code''=v->>''currentCode''and cards->''archive_codes''=jsonb_build_array(v->>''archiveCode''),''both installed policy readbacks required'');
 return jsonb_build_object(''prepared'',true,''competitionId'',c.id,''active'',false,''noUsers'',true,''coldState'',cold,''sourcePolicy'',c.source_policy,''manifestSha256'',p.manifest_sha256,''bindings'',p.bindings,''bindingSha256'',private_baden_history.sha(p.bindings),''history'',history,''cards'',cards,''policySha256'',history->>''policySha256'',''markerInventorySha256'',private_baden_history.sha(history->''markers''),''firstFantasyPlayedOn'',history->>''firstFantasyPlayedOn'',''openingRoundId'',opening.id);
end';
create or replace function public.get_fussball_historical_preparation(p_competition_id bigint)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin if exists(select 1 from private_baden_transition.versions where competition_id=p_competition_id)then return private_baden_transition.m2_cold(p_competition_id);end if;return private_baden_transition.m1_cold(p_competition_id);end$$;
do $clone$begin if(select encode(sha256(convert_to(prosrc,'UTF8')),'hex')from pg_proc where oid='public.get_fussball_historical_runtime(bigint)'::regprocedure)<>'37e07afe664ba47b049537ea92f033bc3627007328cfb08a81bb645f6549e895'then raise exception 'BADEN_VERSION: exact runtime predecessor required';end if;end$clone$;
create function private_baden_transition.m1_runtime(p_competition_id bigint)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as '
#variable_conflict use_column
declare c competitions;p private_baden_history.prepared;v jsonb;b jsonb;f jsonb;r rounds;m matches;history jsonb;cards jsonb;
begin
 perform private_fussball.service();
 select * into c from competitions where id=p_competition_id;
 select * into p from private_baden_history.prepared where competition_id=c.id;
 select manifest into v from private_baden_history.catalog where singleton and manifest_sha256=p.manifest_sha256;
 perform private_baden_history.require(v is not null and private_baden_history.sha(v)=p.manifest_sha256 and private_baden_history.exact_policy(v->''policy'') and c.slug=''de-verbandsliga-baden'' and c.slug=v->>''slug'' and c.source=''fussball-public'' and c.source_league_code=v->>''currentCode'' and c.source_policy=''fussball-community-cards-v1'' and exists(select 1 from countries where id=c.country_id and code=''DE''),''exact compiled installed Baden runtime required'');
 perform private_baden_history.require(jsonb_array_length(p.bindings)=jsonb_array_length(v->''fixtures'') and (select count(distinct q->>''matchId'') from jsonb_array_elements(p.bindings)q)=jsonb_array_length(p.bindings) and (select count(distinct(q->>''sourceCompetitionId'',q->>''sourceMatchId'')) from jsonb_array_elements(p.bindings)q)=jsonb_array_length(p.bindings),''complete unique runtime native bindings required'');
 for b in select value from jsonb_array_elements(p.bindings) loop
  f:=b->''fixture'';select * into r from rounds where id=(b->>''roundId'')::bigint;select * into m from matches where id=(b->>''matchId'')::bigint;
  perform private_baden_history.require(exists(select 1 from jsonb_array_elements(v->''fixtures'')x where x=f) and r.competition_id=c.id and r.season=f->>''season'' and r.number=(f->>''round'')::int and m.round_id=r.id and m.home_team_id=(b->>''homeTeamId'')::bigint and m.away_team_id=(b->>''awayTeamId'')::bigint and m.zapisnik_id=f->>''reportId'' and m.source_url=f->>''sourceUrl''
   and exists(select 1 from private_baden_history.club_bindings cb join teams t on t.id=cb.team_id where cb.competition_id=c.id and cb.source_competition_id=f->>''sourceCompetitionId'' and cb.season=f->>''season'' and cb.source_club_id=f->>''homeSourceClubId'' and cb.name=f->>''homeName'' and cb.team_id=m.home_team_id and t.country_id=c.country_id and t.name=cb.name)
   and exists(select 1 from private_baden_history.club_bindings cb join teams t on t.id=cb.team_id where cb.competition_id=c.id and cb.source_competition_id=f->>''sourceCompetitionId'' and cb.season=f->>''season'' and cb.source_club_id=f->>''awaySourceClubId'' and cb.name=f->>''awayName'' and cb.team_id=m.away_team_id and t.country_id=c.country_id and t.name=cb.name),''full runtime source/native binding drift'');
  -- Ordinary current reports/date changes are authorized by the ordinary import
  -- path; only immutable markers must retain the complete original header.
  if (f->>''unavailable'')::boolean then
   perform private_baden_history.require(m.statistics_status=''unavailable_historical'' and m.imported_at is null and not m.vir_brez_izida and not m.kontumacija and m.played_on=(f->>''date'')::date and m.source_phase is null and m.source_round=(f->>''round'')::int
    and m.home_goals is not distinct from(f#>>''{score,domaci}'')::int and m.away_goals is not distinct from(f#>>''{score,gostje}'')::int
    and not exists(select 1 from appearances where match_id=m.id) and not exists(select 1 from goals where match_id=m.id) and not exists(select 1 from private_fussball.card_reports where match_id=m.id),''immutable runtime marker/header/individual/card drift'');
  else perform private_baden_history.require(m.statistics_status in(''available'',''pending_cards''),''ordinary fixture cannot acquire historical exclusion'');end if;
 end loop;
 perform private_baden_history.require((select count(*)from matches m join rounds r on r.id=m.round_id where r.competition_id=c.id)=jsonb_array_length(p.bindings),''extra/missing runtime native fixture'');
 history:=public.get_installed_historical_statistics_markers(c.id);cards:=public.get_fussball_card_policy(c.id);
 perform private_baden_history.require(history->>''installed''=''true'' and history->>''policySha256''=private_baden_history.sha(v->''policy'') and history->>''firstFantasyPlayedOn''=v->>''firstFantasyPlayedOn'' and cards->>''installed''=''true'' and cards->>''enabled''=''true'' and cards->>''source_policy''=c.source_policy and cards->>''current_code''=v->>''currentCode'' and cards->''archive_codes''=jsonb_build_array(v->>''archiveCode''),''both complete runtime policies required'');
 return jsonb_build_object(''kind'',''baden-bound-installed-runtime'',''competitionId'',c.id,''active'',c.active,''manifest'',v,''manifestSha256'',p.manifest_sha256,''bindings'',p.bindings,''bindingSha256'',private_baden_history.sha(p.bindings),''history'',history,''cards'',cards,''policySha256'',history->>''policySha256'',''markerInventorySha256'',private_baden_history.sha(history->''markers''),''firstFantasyPlayedOn'',history->>''firstFantasyPlayedOn'',''openingRoundId'',p.opening_round_id,''registrationEligible'',false,''activationEligible'',false);
end';
