create or replace function public.get_fussball_historical_runtime(p_competition_id bigint)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin if exists(select 1 from private_baden_transition.versions where competition_id=p_competition_id)then return private_baden_transition.m2_runtime(p_competition_id);end if;return private_baden_transition.m1_runtime(p_competition_id);end$$;
do $clone$begin if(select encode(sha256(convert_to(prosrc,'UTF8')),'hex')from pg_proc where oid='private_baden_history.launch_counts(bigint)'::regprocedure)<>'334bfbc07e844ecd0711a36b1d404c3e154db5678b44ba2938a3618ee5ec52fc'then raise exception 'BADEN_VERSION: exact counts predecessor required';end if;end$clone$;
create function private_baden_transition.m1_counts(cid bigint)returns jsonb language sql stable security definer set search_path=public,pg_temp as '
 select jsonb_agg(jsonb_build_object(''code'',scope.code,''season'',split_part(scope.code,'':'',2),''unplayed'',n.unplayed,''complete'',n.complete,''community-pending'',n.pending,''reviewed-known-result-unavailable'',n.known,''reviewed-unknown-administrative-result'',n.unknown)order by scope.ord)
 from private_baden_history.prepared p join private_baden_history.catalog cat on cat.manifest_sha256=p.manifest_sha256
 cross join lateral(values(cat.manifest->>''currentCode'',1),(cat.manifest->>''archiveCode'',2))scope(code,ord)
 cross join lateral(select count(*)filter(where b#>''{fixture,score}''=''null''::jsonb and not(b#>>''{fixture,unavailable}'')::boolean)unplayed,
 count(*)filter(where not(b#>>''{fixture,unavailable}'')::boolean and b#>''{fixture,score}''<>''null''::jsonb and m.statistics_status=''available'')complete,
 count(*)filter(where m.statistics_status=''pending_cards'')pending,
 count(*)filter(where(b#>>''{fixture,unavailable}'')::boolean and b#>''{fixture,score}''<>''null''::jsonb)known,
 count(*)filter(where(b#>>''{fixture,unavailable}'')::boolean and b#>''{fixture,score}''=''null''::jsonb)unknown
 from jsonb_array_elements(p.bindings)b join matches m on m.id=(b->>''matchId'')::bigint where b->>''sourceCompetitionId''=scope.code)n
 where p.competition_id=cid
';
create function private_baden_transition.m2_counts(cid bigint)returns jsonb language sql stable security definer set search_path=public,pg_temp as '
 select jsonb_agg(jsonb_build_object(''code'',scope.code,''season'',split_part(scope.code,'':'',2),''unplayed'',n.unplayed,''complete'',n.complete,''community-pending'',n.pending,''reviewed-known-result-unavailable'',n.known,''reviewed-unknown-administrative-result'',n.unknown)order by scope.ord)
 from private_baden_transition.effective_prepared p join private_baden_transition.effective_catalog cat on cat.manifest_sha256=p.manifest_sha256
 cross join lateral(values(cat.manifest->>''currentCode'',1),(cat.manifest->>''archiveCode'',2))scope(code,ord)
 cross join lateral(select count(*)filter(where b#>''{fixture,score}''=''null''::jsonb and not(b#>>''{fixture,unavailable}'')::boolean)unplayed,
 count(*)filter(where not(b#>>''{fixture,unavailable}'')::boolean and b#>''{fixture,score}''<>''null''::jsonb and m.statistics_status=''available'')complete,
 count(*)filter(where m.statistics_status=''pending_cards'')pending,
 count(*)filter(where(b#>>''{fixture,unavailable}'')::boolean and b#>''{fixture,score}''<>''null''::jsonb)known,
 count(*)filter(where(b#>>''{fixture,unavailable}'')::boolean and b#>''{fixture,score}''=''null''::jsonb)unknown
 from jsonb_array_elements(p.bindings)b join matches m on m.id=(b->>''matchId'')::bigint where b->>''sourceCompetitionId''=scope.code)n
 where p.competition_id=cid
';
create or replace function private_baden_history.launch_counts(cid bigint)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin if exists(select 1 from private_baden_transition.versions where competition_id=cid)then return private_baden_transition.m2_counts(cid);end if;return private_baden_transition.m1_counts(cid);end$$;
do $guard$begin if(select encode(sha256(convert_to(prosrc,'UTF8')),'hex')from pg_proc where oid='public.prepare_fussball_historical_statistics(text,text)'::regprocedure)<>'fb69d2ce9680057c3babd28c801b9b12e6c3078e52c64d0434d4d24e9ca457e8'then raise exception 'BADEN_VERSION: exact prepare predecessor required';end if;end$guard$;
create function private_baden_transition.m1_prepare(p_manifest text,p_sha256 text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as '
#variable_conflict use_column

declare v jsonb;compiled jsonb;c competitions;f jsonb;e jsonb;x record;ids bigint[];tid bigint;rid bigint;hid bigint;aid bigint;mid bigint;opening bigint;day date;due timestamptz;bindings jsonb:=''[]'';psha text;p jsonb;
begin
 perform private_fussball.service();perform private_baden_history.require(current_setting(''transaction_isolation'')=''read committed'',''READ COMMITTED required'');
 perform private_baden_history.require(octet_length(p_manifest)<=64*1024*1024 and p_sha256~''^[a-f0-9]{64}$'',''bounded canonical manifest required'');v:=p_manifest::jsonb;
 select manifest into compiled from private_baden_history.catalog where singleton and manifest_sha256=p_sha256 for share;
 perform private_baden_history.require(compiled is not null and compiled=v and private_baden_history.sha(v)=p_sha256 and private_fussball.canonical_json(v)=p_manifest,''catalog UNFINALIZED or compiled manifest differs'');
 perform private_baden_history.require(v->>''version''=''1''and v->>''kind''=''baden-atomic-history-cards-preparation''and v->>''slug''=''de-verbandsliga-baden''and v->>''currentCode''=''03188V27L800000JVS5489BTVU7GTVLE-G:2026/27''and v->>''archiveCode''=''02TGLSVQ1800000IVS5489BTVTLPPK10-G:2025/26''and private_baden_history.exact_policy(v->''policy'')and v#>>''{policy,approvalReference}''=''call_e8c944e47b7c42a38afa4f08fda48c23''and (v->>''currentFreshUntil'')::timestamptz>clock_timestamp()and jsonb_array_length(v->''fixtures'')between 2 and 8000 and jsonb_array_length(v#>''{policy,entries}'')between 1 and 1224,''closed finalized exact Baden catalog required'');
 select *into strict c from competitions where slug=''de-verbandsliga-baden''for update;
 lock table countries,teams,players,rounds,matches,appearances,goals,fantasy_teams,fantasy_lineups in share row exclusive mode;
 perform private_baden_history.require(not c.active and c.source=''fussball-public''and c.source_league_code=v->>''currentCode''and(c.source_policy is null or c.source_policy=''fussball-community-cards-v1'')and c.date_only_deadline_policy is null and exists(select 1 from countries where id=c.country_id and code=''DE'')and not exists(select 1 from competitions where id<>c.id and source=c.source and source_league_code in(v->>''currentCode'',v->>''archiveCode''))and not exists(select 1 from fantasy_teams where competition_id=c.id)and not exists(select 1 from fantasy_lineups l join rounds r on r.id=l.round_id where r.competition_id=c.id),''exact inactive no-user target required'');
 if exists(select 1 from private_baden_history.prepared where competition_id=c.id)then
  perform private_baden_history.require(exists(select 1 from private_baden_history.prepared where competition_id=c.id and manifest_sha256=p_sha256),''prepared manifest immutable'');return public.get_fussball_historical_preparation(c.id);
 end if;
 perform private_baden_history.require(not exists(select 1 from players where competition_id=c.id)and not exists(select 1 from matches m join rounds r on r.id=m.round_id where r.competition_id=c.id and(m.imported_at is not null or exists(select 1 from appearances where match_id=m.id)or exists(select 1 from goals where match_id=m.id))),''populated target cannot be prepared'');
 -- Source descriptor includes competition+season+published name. Full fixtures
 -- compile its authority; actual IDs below come only from native unique joins.
 for x in select distinct q->>''sourceCompetitionId''code,q->>''season''season,q->>''homeSourceClubId''club,q->>''homeName''name from jsonb_array_elements(v->''fixtures'')q union select distinct q->>''sourceCompetitionId'',q->>''season'',q->>''awaySourceClubId'',q->>''awayName''from jsonb_array_elements(v->''fixtures'')q loop
  perform private_baden_history.require((x.season=''2026/27''and x.code=v->>''currentCode'')or(x.season=''2025/26''and x.code=v->>''archiveCode''),''exact source club season required'');
  perform private_baden_history.require(x.club=private_fussball.canonical_json(jsonb_build_object(''sourceCompetitionId'',x.code,''season'',x.season,''name'',x.name)),''full source club descriptor required'');
  select array_agg(id order by id)into ids from teams where country_id=c.country_id and name=x.name;
  perform private_baden_history.require(coalesce(cardinality(ids),0)<=1,''ambiguous native club; names alone cannot resolve authority'');
  tid:=ids[1];if tid is null then insert into teams(name,short_name,country_id)values(x.name,x.name,c.country_id)returning id into tid;end if;
  insert into private_baden_history.club_bindings values(c.id,x.code,x.season,x.club,x.name,tid);
  if exists(select 1 from private_historical_statistics.source_club_bindings where provider=''fussball-public''and source_club_id=x.club)then raise exception ''BADEN_HISTORY: existing source club binding cannot be adopted'';end if;
  insert into private_historical_statistics.source_club_bindings(provider,source_club_id,country_code,canonical_names,proofs,bound_team_id)values(''fussball-public'',x.club,''DE'',array[x.name],(select jsonb_agg(q order by q->>''sourceMatchId'')from jsonb_array_elements(v->''fixtures'')q where q->>''homeSourceClubId''=x.club or q->>''awaySourceClubId''=x.club),tid);
 end loop;
 for x in select q->>''season''season,(q->>''round'')::int number,min((q->>''date'')::date)as fixture_day,min(((q->>''date'')::date+(q->>''time'')::time)at time zone ''Europe/Berlin'')-make_interval(hours=>(v->>''deadlineOffsetHours'')::int)due from jsonb_array_elements(v->''fixtures'')q group by 1,2 loop
  select array_agg(id)into ids from rounds where competition_id=c.id and season=x.season and number=x.number;
  perform private_baden_history.require(coalesce(cardinality(ids),0)<=1,''ambiguous native round'');rid:=ids[1];
  if rid is null then insert into rounds(competition_id,season,number,played_on,deadline_at)values(c.id,x.season,x.number,x.fixture_day,x.due)returning id into rid;
  else perform private_baden_history.require(exists(select 1 from rounds where id=rid and played_on=x.fixture_day and deadline_at=x.due and lineups_locked_at is null),''existing native round metadata differs'');end if;
  if x.season=''2026/27''and x.number=(v->>''openingRound'')::int then opening:=rid;day:=x.fixture_day;due:=x.due;end if;
 end loop;
 perform private_baden_history.require(opening is not null and day=(v->>''firstFantasyPlayedOn'')::date and due>clock_timestamp()and (v->>''deadlineOffsetHours'')::int=c.rok_pomak_ur and not exists(select 1 from jsonb_array_elements(v->''fixtures'')q where q->>''season''=''2026/27''and(q->>''round'')::int=(v->>''openingRound'')::int and(q->''score''<>''null''::jsonb or q->''administrativeResult''<>''null''::jsonb)),''actual wholly unplayed future opening required'');
 p:=v->''policy'';psha:=private_baden_history.sha(p);
 if exists(select 1 from private_historical_statistics.policies where id=p->>''id'')then
  perform private_baden_history.require(exists(select 1 from private_historical_statistics.policies where id=p->>''id''and document=p and policy_sha256=psha),''compiled policy drift'');
 else insert into private_historical_statistics.policies values(p->>''id'',psha,p);end if;
 perform public.install_fussball_card_policy(c.id,v->>''currentCode'',array[v->>''archiveCode'']);
 update competitions set prvi_fantasy_krog=(v->>''openingRound'')::int where id=c.id;
 insert into private_historical_statistics.installed_policies(competition_id,policy_id,policy_sha256,first_fantasy_played_on)values(c.id,p->>''id'',psha,day);
 for f in select value from jsonb_array_elements(v->''fixtures'')order by value->>''sourceMatchId''loop
  select id into strict rid from rounds where competition_id=c.id and season=f->>''season''and number=(f->>''round'')::int;
  select team_id into strict hid from private_baden_history.club_bindings where competition_id=c.id and source_club_id=f->>''homeSourceClubId''and source_competition_id=f->>''sourceCompetitionId''and season=f->>''season'';
  select team_id into strict aid from private_baden_history.club_bindings where competition_id=c.id and source_club_id=f->>''awaySourceClubId''and source_competition_id=f->>''sourceCompetitionId''and season=f->>''season'';
  perform private_baden_history.require(f->>''reportId''=''de-fussball-''||(f->>''sourceMatchId'')and f->>''sourceMatchId''~''^[A-Z0-9]{32}$''and hid<>aid,''exact source fixture/report required'');
  if(f->>''unavailable'')::boolean then
   select value into strict e from jsonb_array_elements(p->''entries'')where value->>''sourceMatchId''=f->>''sourceMatchId'';
   perform private_baden_history.require(e->>''sourceCompetitionId''=f->>''sourceCompetitionId''and e->>''season''=f->>''season''and e->>''sourceUrl''=f->>''sourceUrl''and e->>''playedOn''=f->>''date''and e->>''sourceRound''=f->>''round''and e->>''homeSourceClubId''=f->>''homeSourceClubId''and e->>''awaySourceClubId''=f->>''awaySourceClubId'',''reviewed full tuple differs'');
   perform public.upsert_unavailable_historical_match(c.id,e->>''sourceMatchId'',p->>''id'',psha,e->>''rawSha256'',jsonb_build_object(''fixture'',e-array[''rawSha256'',''reasonCode''],''roundId'',rid,''homeTeamId'',hid,''awayTeamId'',aid));
  else
   perform private_baden_history.require(f->''administrativeResult''=''null''::jsonb,''administrative fixture needs exact review'');
   select array_agg(id)into ids from matches where zapisnik_id=f->>''reportId''or(round_id=rid and home_team_id=hid and away_team_id=aid);
   perform private_baden_history.require(coalesce(cardinality(ids),0)=0,''existing nonmarker headers cannot be adopted in cold preparation'');
   insert into matches(round_id,home_team_id,away_team_id,home_goals,away_goals,played_on,zapisnik_id,source_url,source_round,vir_brez_izida)values(rid,hid,aid,coalesce((f#>>''{score,domaci}'')::int,0),coalesce((f#>>''{score,gostje}'')::int,0),(f->>''date'')::date,f->>''reportId'',f->>''sourceUrl'',(f->>''round'')::int,f->''score''=''null''::jsonb);
  end if;
  select id into strict mid from matches where round_id=rid and home_team_id=hid and away_team_id=aid and zapisnik_id=f->>''reportId''and source_url=f->>''sourceUrl''and played_on=(f->>''date'')::date;
  bindings:=bindings||jsonb_build_array(jsonb_build_object(''sourceMatchId'',f->>''sourceMatchId'',''sourceCompetitionId'',f->>''sourceCompetitionId'',''fixture'',f,''matchId'',mid,''roundId'',rid,''homeTeamId'',hid,''awayTeamId'',aid));
 end loop;
 insert into private_baden_history.prepared values(c.id,p_sha256,bindings,opening);
 return public.get_fussball_historical_preparation(c.id);
end';
create or replace function public.prepare_fussball_historical_statistics(p_manifest text,p_sha256 text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin perform private_fussball.service();if exists(select 1 from private_baden_transition.versions)then perform private_baden_history.require(exists(select 1 from private_baden_transition.versions where manifest_sha256=p_sha256 and manifest=p_manifest::jsonb and private_fussball.canonical_json(manifest)=p_manifest),'old or different M rejected after version selection');return public.get_fussball_historical_preparation(1132);end if;return private_baden_transition.m1_prepare(p_manifest,p_sha256);end$$;
do $guard$begin if(select encode(sha256(convert_to(prosrc,'UTF8')),'hex')from pg_proc where oid='private_fussball.admission_state(bigint)'::regprocedure)<>'e049efec1b2a9df77f61d8ac6808d0aabbefc63d25bdaa37d92fa17ca711c05c'then raise exception 'BADEN_VERSION: exact admission state predecessor required';end if;end$guard$;
create or replace function private_fussball.admission_state(cid bigint)returns text language sql stable security definer set search_path=public,pg_temp as '
 select case when exists(select 1 from private_baden_transition.effective_prepared where competition_id=cid)then private_baden_history.sha(jsonb_build_object(''cardsNative'',private_fussball.admission_state_cards_v1(cid),''prepared'',(select to_jsonb(p)from private_baden_transition.effective_prepared p where competition_id=cid),''history'',public.get_installed_historical_statistics_markers(cid),''runtime'',public.get_fussball_historical_runtime(cid)-''active''))else private_fussball.admission_state_cards_v1(cid)end
';
-- Mutation authority is session/role ownership, never a caller-set JWT/GUC.
create function private_baden_transition.owner_only()returns void language plpgsql security invoker set search_path=pg_catalog as $$begin
 if current_user<>session_user or current_user not in('postgres','supabase_admin')or not exists(select 1 from pg_roles where rolname=session_user and rolsuper)then raise exception 'BADEN_VERSION: actual super owner session required'using errcode='42501';end if;
end$$;
create function private_baden_transition.state()returns jsonb language plpgsql volatile security invoker set search_path=public,pg_temp set timezone='UTC' as $$declare t record;n bigint;h text;rels jsonb:='{}';cat jsonb;target jsonb;begin
 for t in select ns.nspname,c.relname from pg_class c join pg_namespace ns on ns.oid=c.relnamespace where c.relkind in('r','p')and(ns.nspname in('public','scout')or ns.nspname like'private\_%'escape'\'or(ns.nspname='auth'and c.relname='users'))and not(ns.nspname='private_baden_transition'and c.relname='versions')order by ns.nspname,c.relname loop
 execute format('select count(*),encode(sha256(convert_to(coalesce(string_agg(h,''''order by h collate "C"),''''),''UTF8'')),''hex'')from(select encode(sha256(convert_to(to_jsonb(x)::text,''UTF8'')),''hex'')h from %I.%I x)s',t.nspname,t.relname)into n,h;
 rels:=rels||jsonb_build_object(t.nspname||'.'||t.relname,jsonb_build_object('count',n,'sortedFullRowDigestSha256',h));end loop;
 select jsonb_agg(jsonb_build_array(ns.nspname,c.relname,a.attname,a.atttypid::regtype::text,a.attnotnull)order by ns.nspname,c.relname,a.attnum)into cat from pg_class c join pg_namespace ns on ns.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid where c.relkind in('r','p')and a.attnum>0 and not a.attisdropped and(ns.nspname in('public','scout')or ns.nspname like'private\_%'escape'\');
 select jsonb_build_object('competition',(select to_jsonb(c)from competitions c where id=1132),'catalog',(select jsonb_agg(to_jsonb(c))from private_baden_history.catalog c),'prepared',(select to_jsonb(p)from private_baden_history.prepared p where competition_id=1132),'rounds',(select jsonb_agg(to_jsonb(r)order by id)from rounds r where competition_id=1132),'matches',(select jsonb_agg(to_jsonb(m)order by m.id)from matches m join rounds r on r.id=m.round_id where r.competition_id=1132),'offTargetRounds',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r)order by id),'[]')::text,'UTF8')),'hex')from rounds r where competition_id<>1132),'offTargetMatches',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(m)order by m.id),'[]')::text,'UTF8')),'hex')from matches m where not exists(select 1 from rounds r where r.id=m.round_id and r.competition_id=1132)))into target;
 return jsonb_build_object('relations',rels,'columns',cat,'target',target,'constraints',(select jsonb_agg(jsonb_build_array(conrelid::regclass::text,conname,pg_get_constraintdef(oid),convalidated,condeferrable,condeferred)order by conrelid::regclass::text,conname)from pg_constraint where conrelid in(select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','scout')or n.nspname like'private\_%'escape'\')),'triggers',(select jsonb_agg(jsonb_build_array(t.tgrelid::regclass::text,t.tgname,pg_get_triggerdef(t.oid),t.tgenabled,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'))order by t.tgrelid::regclass::text,t.tgname)from pg_trigger t join pg_proc p on p.oid=t.tgfoid where not t.tgisinternal and t.tgrelid in(select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','scout')or n.nspname like'private\_%'escape'\')));
end$$;
create function private_baden_transition.validate(t text,h text,s jsonb)returns jsonb language plpgsql volatile security invoker set search_path=public,pg_temp as $$declare oldm jsonb;v jsonb;b jsonb;f jsonb;n jsonb;c competitions;r rounds;m matches;p private_baden_history.prepared;nextbindings jsonb:='[]';day date;due timestamptz;begin
 perform private_baden_transition.owner_only();perform private_baden_transition.closure();
 perform private_baden_history.require(octet_length(t)between 2 and 4194304 and h~'^[a-f0-9]{64}$'and encode(sha256(convert_to(t,'UTF8')),'hex')=h,'bounded canonical new M2 TEXT/SHA');v:=t::jsonb;
 select manifest into strict oldm from private_baden_history.catalog where singleton and manifest_sha256='781b1784038fef6bdf223a8d127430d8ed37f76031126db62e3f1ef20d6e019e';
 perform private_baden_history.require(private_baden_history.sha(oldm)='781b1784038fef6bdf223a8d127430d8ed37f76031126db62e3f1ef20d6e019e'and private_fussball.canonical_json(v)=t and h<>private_baden_history.sha(oldm),'exact original expired M1 is beforeimage only');
 perform private_baden_history.require(v-array['currentFreshUntil','derivedPackSha256','sourceCertificateSha256','catalogSha256','fixtures']=oldm-array['currentFreshUntil','derivedPackSha256','sourceCertificateSha256','catalogSha256','fixtures'],'same immutable policy/frontier/opening route only');
 perform private_baden_history.require(octet_length(s::text)<=65536 and (select array_agg(k order by k)from jsonb_object_keys(s)k)=array['catalogSha256','currentCreatedAt','currentFreshUntil','derivedHead','derivedPackSha256','derivedRunId','kind','sourceCertificateSha256','sourceHead','sourceOperationAuthorized','sourceRunId'],'closed source binding DATA; not serialized proof authority');
 perform private_baden_history.require(s->>'kind'='baden-cold-source-binding-DATA'and s->'sourceOperationAuthorized'='false'::jsonb and s->>'sourceRunId'~'^[1-9][0-9]{0,19}$'and s->>'sourceRunId'<>'40859714195'and s->>'derivedRunId'~'^[1-9][0-9]{0,19}$'and s->>'derivedRunId'<>'40990176474'and s->>'sourceHead'~'^[a-f0-9]{40}$'and s->>'derivedHead'~'^[a-f0-9]{40}$'and(s->>'currentCreatedAt')::timestamptz<=clock_timestamp()and(s->>'currentFreshUntil')::timestamptz=(s->>'currentCreatedAt')::timestamptz+interval'24 hours'and(s->>'currentFreshUntil')::timestamptz>clock_timestamp()and s->>'currentFreshUntil'=v->>'currentFreshUntil'and not exists(select 1 from unnest(array['derivedPackSha256','catalogSha256','sourceCertificateSha256'])k where v->>k is not distinct from oldm->>k or v->>k!~'^[a-f0-9]{64}$'or v->>k is distinct from s->>k),'distinct actual source/derive clock DATA; genuine private issuer/owner operator required outside SQL');
 select *into strict c from competitions where id=1132;select *into strict p from private_baden_history.prepared where competition_id=1132;
 perform private_baden_history.require(not c.active and c.slug='de-verbandsliga-baden'and c.source='fussball-public'and c.source_policy='fussball-community-cards-v1'and c.source_league_code=v->>'currentCode'and c.prvi_fantasy_krog=(v->>'openingRound')::int and c.rok_pomak_ur=(v->>'deadlineOffsetHours')::int and c.date_only_deadline_policy is null and exists(select 1 from countries where id=c.country_id and code='DE')and p.manifest_sha256=private_baden_history.sha(oldm),'exact actual inactive source-policy/native M1');
 perform private_baden_history.require(not exists(select 1 from players where competition_id=c.id)and not exists(select 1 from matches x join rounds y on y.id=x.round_id where y.competition_id=c.id and(x.imported_at is not null or exists(select 1 from appearances where match_id=x.id)or exists(select 1 from goals where match_id=x.id)))and not exists(select 1 from player_scores x join rounds y on y.id=x.round_id where y.competition_id=c.id)and not exists(select 1 from tocke_krogov x join rounds y on y.id=x.round_id where y.competition_id=c.id)and not exists(select 1 from ratings x join rounds y on y.id=x.round_id where y.competition_id=c.id),'all actual cold individual/points/ratings counts0');
 perform private_baden_history.require(not exists(select 1 from private_fussball.card_reports cr where cr.competition_id=c.id or cr.match_id in(select x.id from matches x join rounds y on y.id=x.round_id where y.competition_id=c.id))and not exists(select 1 from private_fussball.card_admissions where competition_id=c.id)and not exists(select 1 from private_fussball.card_activation_context where competition_id=c.id)and not exists(select 1 from private_fussball.card_heads h join matches x on x.id=h.match_id join rounds y on y.id=x.round_id where y.competition_id=c.id)and not exists(select 1 from private_fussball.card_write_context h join matches x on x.id=h.match_id join rounds y on y.id=x.round_id where y.competition_id=c.id),'all actual card/vote/admission/context counts0');
 perform private_baden_history.require(exists(select 1 from private_historical_statistics.installed_policies i join private_historical_statistics.policies d on d.id=i.policy_id where i.competition_id=c.id and d.document=oldm->'policy'and d.policy_sha256=private_baden_history.sha(d.document)and i.policy_sha256=d.policy_sha256 and i.first_fantasy_played_on=(v->>'firstFantasyPlayedOn')::date),'immutable real installed firstFantasyDay and policy; no invented cutoff');
 perform private_baden_history.require(jsonb_array_length(v->'fixtures')=jsonb_array_length(oldm->'fixtures')and jsonb_array_length(p.bindings)=jsonb_array_length(v->'fixtures')and(select count(distinct(f->>'sourceCompetitionId',f->>'sourceMatchId'))from jsonb_array_elements(v->'fixtures')f)=jsonb_array_length(v->'fixtures')and(select count(*)from matches x join rounds y on y.id=x.round_id where y.competition_id=c.id)=jsonb_array_length(p.bindings),'full exact unique actual fixture/native frontier');
 perform private_baden_history.require((select count(distinct b->>'matchId')from jsonb_array_elements(p.bindings)b)=jsonb_array_length(p.bindings)and(select count(distinct(b->>'sourceCompetitionId',b->>'sourceMatchId'))from jsonb_array_elements(p.bindings)b)=jsonb_array_length(p.bindings)and(select count(*)from rounds where competition_id=1132)=(select count(distinct(f->>'season',f->>'round'))from jsonb_array_elements(oldm->'fixtures')f),'no duplicate native binding or extra empty source round');
 perform private_baden_history.require((select count(*)from private_historical_statistics.markers where competition_id=1132)=jsonb_array_length(oldm#>'{policy,entries}')and not exists(select 1 from jsonb_array_elements(oldm#>'{policy,entries}')e where not exists(select 1 from private_historical_statistics.markers k where k.competition_id=1132 and k.source_match_id=e->>'sourceMatchId'and k.source_report_id='de-fussball-'||(e->>'sourceMatchId')and k.fixture=e-array['rawSha256','reasonCode']and k.raw_sha256 is not distinct from e->>'rawSha256')),'every immutable actual reviewed marker present byte-exact');
 perform private_baden_history.require((select count(*)from private_baden_history.club_bindings where competition_id=1132)=(select count(distinct club)from(select f->>'homeSourceClubId'club from jsonb_array_elements(oldm->'fixtures')f union select f->>'awaySourceClubId'from jsonb_array_elements(oldm->'fixtures')f)x)and not exists(select 1 from private_baden_history.club_bindings b where b.competition_id=1132 and not exists(select 1 from private_historical_statistics.source_club_bindings g where g.provider='fussball-public'and g.source_club_id=b.source_club_id and g.bound_team_id=b.team_id and g.country_code='DE'and g.canonical_names=array[b.name]and g.proofs=(select jsonb_agg(f order by f->>'sourceMatchId')from jsonb_array_elements(oldm->'fixtures')f where f->>'homeSourceClubId'=b.source_club_id or f->>'awaySourceClubId'=b.source_club_id))),'exact original full source club proof frontier');
 for b in select value from jsonb_array_elements(p.bindings)loop
  f:=b->'fixture';select value into strict n from jsonb_array_elements(v->'fixtures')q where q->>'sourceCompetitionId'=f->>'sourceCompetitionId'and q->>'sourceMatchId'=f->>'sourceMatchId';
  perform private_baden_history.require(exists(select 1 from jsonb_array_elements(oldm->'fixtures')q where q=f)and n-array['date','time','score']=f-array['date','time','score']and(f->>'unavailable'<>'true'and f->>'season'<>'2025/26'and not(f->>'season'='2026/27'and f->>'round'=v->>'openingRound')or n=f),'marker/archive/opening and source/club identity immutable');
  perform private_baden_history.require(n->>'date'~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$'and n->>'time'~'^([01][0-9]|2[0-3]):[0-5][0-9]$'and(n->'score'='null'::jsonb or jsonb_typeof(n->'score')='object'and(select array_agg(k order by k)from jsonb_object_keys(n->'score')k)=array['domaci','gostje']and jsonb_typeof(n#>'{score,domaci}')='number'and jsonb_typeof(n#>'{score,gostje}')='number'and(n#>>'{score,domaci}')~'^[0-9]+$'and(n#>>'{score,gostje}')~'^[0-9]+$'and(n->>'date')::date<=(clock_timestamp()at time zone'Europe/Berlin')::date),'official source date/kickoff/score only');
  select *into strict r from rounds where id=(b->>'roundId')::bigint;select *into strict m from matches where id=(b->>'matchId')::bigint;
  perform private_baden_history.require(r.competition_id=c.id and r.season=f->>'season'and r.number=(f->>'round')::int and m.round_id=r.id and m.home_team_id=(b->>'homeTeamId')::bigint and m.away_team_id=(b->>'awayTeamId')::bigint and m.zapisnik_id=f->>'reportId'and m.source_url=f->>'sourceUrl'and m.played_on=(f->>'date')::date and m.source_round=(f->>'round')::int and m.source_phase is null and m.imported_at is null and not m.kontumacija and m.statistics_status=case when(f->>'unavailable')::boolean then'unavailable_historical'else'available'end and m.home_goals is not distinct from coalesce((f#>>'{score,domaci}')::int,case when(f->>'unavailable')::boolean then null else 0 end)and m.away_goals is not distinct from coalesce((f#>>'{score,gostje}')::int,case when(f->>'unavailable')::boolean then null else 0 end),'full exact original source/native header beforeimage');
  perform private_baden_history.require(exists(select 1 from private_baden_history.club_bindings cb join teams x on x.id=cb.team_id where cb.competition_id=c.id and cb.source_competition_id=f->>'sourceCompetitionId'and cb.season=f->>'season'and cb.source_club_id=f->>'homeSourceClubId'and cb.name=f->>'homeName'and x.id=m.home_team_id and x.country_id=c.country_id and x.name=cb.name)and exists(select 1 from private_baden_history.club_bindings cb join teams x on x.id=cb.team_id where cb.competition_id=c.id and cb.source_competition_id=f->>'sourceCompetitionId'and cb.season=f->>'season'and cb.source_club_id=f->>'awaySourceClubId'and cb.name=f->>'awayName'and x.id=m.away_team_id and x.country_id=c.country_id and x.name=cb.name),'unchanged actual native clubs');
  nextbindings:=nextbindings||jsonb_build_array(jsonb_set(b,'{fixture}',n));
 end loop;
 select *into strict r from rounds where id=p.opening_round_id;perform private_baden_history.require(r.competition_id=1132 and r.season='2026/27'and r.number=(v->>'openingRound')::int,'exact opening native identity');
 select min((q->>'date')::date),min(((q->>'date')::date+(q->>'time')::time)at time zone'Europe/Berlin')-make_interval(hours=>(v->>'deadlineOffsetHours')::int)into day,due from jsonb_array_elements(v->'fixtures')q where q->>'season'='2026/27'and q->>'round'=v->>'openingRound';
 perform private_baden_history.require(day=(v->>'firstFantasyPlayedOn')::date and day>(clock_timestamp()at time zone'Europe/Berlin')::date and due>clock_timestamp()and r.lineups_locked_at is null and not exists(select 1 from jsonb_array_elements(v->'fixtures')q where q->>'season'='2026/27'and q->>'round'=v->>'openingRound'and(q->'score'<>'null'::jsonb or q->'administrativeResult'<>'null'::jsonb)),'same wholly unplayed future unlocked official opening');
 return jsonb_build_object('manifest',v,'bindings',nextbindings,'openingRoundId',p.opening_round_id);
end$$;
create function private_baden_transition.require_locks()returns void language plpgsql security invoker set search_path=pg_catalog as $$begin
 perform private_baden_history.require(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in('r','p')and(n.nspname in('public','scout')or n.nspname like'private\_%'escape'\'or(n.nspname='auth'and c.relname='users'))and not exists(select 1 from pg_locks l where l.pid=pg_backend_pid()and l.relation=c.oid and l.granted and l.mode in('ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock'))),'complete actual dependency locks, including newly observed relations');
end$$;
create function private_baden_transition.preview(t text,h text,s jsonb)returns jsonb language plpgsql volatile security invoker set search_path=public,pg_temp as $$declare p jsonb;b text;begin
 perform private_baden_transition.owner_only();perform private_baden_history.require(current_setting('transaction_read_only')='on'and current_setting('transaction_isolation')='repeatable read','explicit coherent owner REPEATABLE READ READ ONLY preview required');p:=private_baden_transition.validate(t,h,s);b:=private_baden_transition.state()::text;perform private_baden_history.require((t::jsonb->>'currentFreshUntil')::timestamptz>clock_timestamp(),'new source fresh after coherent preview');
 return jsonb_build_object('kind','baden-cold-source-preview-DATA','beforeImageText',b,'beforeSha256',encode(sha256(convert_to(b,'UTF8')),'hex'),'newManifestSha256',h,'proposal',p,'sourceOperationAuthorized',false,'nativeAdmission',false,'activationEligible',false);
end$$;
create function private_baden_transition.readback(h text)returns jsonb language plpgsql volatile security invoker set search_path=public,pg_temp as $$declare v private_baden_transition.versions;s jsonb;begin
 perform private_baden_transition.owner_only();if current_setting('transaction_read_only')='on'then perform private_baden_history.require(current_setting('transaction_isolation')='repeatable read','coherent owner readback isolation required');else perform private_baden_transition.require_locks();end if;select *into v from private_baden_transition.versions where manifest_sha256=h;if v.singleton is null then return jsonb_build_object('outcome','UNKNOWN','writeAllowed',false);end if;perform private_baden_history.require(private_baden_history.sha(v.manifest)=v.manifest_sha256 and encode(sha256(convert_to(v.before_image_text,'UTF8')),'hex')=v.before_sha256,'exact independently hashed durable version record');s:=private_baden_transition.state();return jsonb_build_object('outcome',case when s=v.after_state then'COMMITTED'else'COMMITTED_WITH_DRIFT_HOLD'end,'writeAllowed',false,'manifestSha256',v.manifest_sha256,'oldManifestSha256',v.old_manifest_sha256,'beforeSha256',v.before_sha256,'sourceBinding',v.source_binding,'sourceFresh',(v.manifest->>'currentFreshUntil')::timestamptz>clock_timestamp(),'sourceOperationAuthorized',false,'nativeAdmission',false,'activationEligible',false);
end$$;
create function private_baden_transition.apply(t text,h text,s jsonb,before_text text,before_sha text)returns jsonb language plpgsql volatile security invoker set search_path=public,pg_temp as $$declare prior jsonb;after jsonb;p jsonb;f jsonb;r record;b jsonb;n jsonb;stored private_baden_transition.versions;begin
 perform private_baden_transition.owner_only();perform private_baden_history.require(current_setting('transaction_isolation')='read committed'and current_setting('transaction_read_only')='off','actual writable READ COMMITTED owner transaction required');
 perform private_fcf_future_import.lock_dependencies();lock table auth.users in share row exclusive mode;perform private_baden_transition.require_locks();
 select *into stored from private_baden_transition.versions;
 if stored.singleton is not null then perform private_baden_history.require(stored.manifest_sha256=h and private_fussball.canonical_json(stored.manifest)=t and stored.source_binding=s and stored.before_image_text=before_text and stored.before_sha256=before_sha,'exact original selected payload only; no blind retry');return private_baden_transition.readback(h);end if;
 prior:=private_baden_transition.state();perform private_baden_history.require(octet_length(before_text)<=67108864 and before_sha~'^[a-f0-9]{64}$'and encode(sha256(convert_to(before_text,'UTF8')),'hex')=before_sha and before_text=prior::text,'full actual coherent beforeimage under complete dependency locks');
 p:=private_baden_transition.validate(t,h,s);
 for b in select value from jsonb_array_elements(p->'bindings')loop f:=b->'fixture';if not(f->>'unavailable')::boolean then update matches set played_on=(f->>'date')::date,home_goals=coalesce((f#>>'{score,domaci}')::int,0),away_goals=coalesce((f#>>'{score,gostje}')::int,0),vir_brez_izida=f->'score'='null'::jsonb where id=(b->>'matchId')::bigint;end if;end loop;
 for r in select q->>'season'season,(q->>'round')::int rn,min((q->>'date')::date) AS source_day,min(((q->>'date')::date+(q->>'time')::time)at time zone'Europe/Berlin')-make_interval(hours=>((p->'manifest')->>'deadlineOffsetHours')::int)due from jsonb_array_elements(p#>'{manifest,fixtures}')q group by 1,2 loop update rounds set played_on=r.source_day,deadline_at=r.due where competition_id=1132 and season=r.season and number=r.rn;end loop;
 for b in select value from jsonb_array_elements(p->'bindings')loop f:=b->'fixture';if not(f->>'unavailable')::boolean then perform private_baden_history.require(exists(select 1 from matches m where m.id=(b->>'matchId')::bigint and m.played_on=(f->>'date')::date and m.home_goals=coalesce((f#>>'{score,domaci}')::int,0)and m.away_goals=coalesce((f#>>'{score,gostje}')::int,0)and m.vir_brez_izida=(f->'score'='null'::jsonb)),'independent exact ordinary post-header source values');end if;end loop;
 for r in select q->>'season'season,(q->>'round')::int rn,min((q->>'date')::date) AS source_day,min(((q->>'date')::date+(q->>'time')::time)at time zone'Europe/Berlin')-make_interval(hours=>((p->'manifest')->>'deadlineOffsetHours')::int)due from jsonb_array_elements(p#>'{manifest,fixtures}')q group by 1,2 loop perform private_baden_history.require(exists(select 1 from rounds x where x.competition_id=1132 and x.season=r.season and x.number=r.rn and x.played_on=r.source_day and x.deadline_at=r.due),'independent exact official post-calendar values');end loop;
 after:=private_baden_transition.state();
 perform private_baden_history.require(prior-array['relations','target']=after-array['relations','target']and prior#>'{target,competition}'=after#>'{target,competition}'and prior#>'{target,catalog}'=after#>'{target,catalog}'and prior#>'{target,prepared}'=after#>'{target,prepared}'and prior#>'{target,offTargetRounds}'=after#>'{target,offTargetRounds}'and prior#>'{target,offTargetMatches}'=after#>'{target,offTargetMatches}'and not exists(select 1 from jsonb_each(prior->'relations')x where x.key not in('public.matches','public.rounds')and x.value is distinct from after#>array['relations',x.key]),'all old rows/catalog/triggers and every off-target relation/points/prices conserved');
 perform private_baden_history.require(not exists(select 1 from jsonb_array_elements(prior#>'{target,matches}')x left join jsonb_array_elements(after#>'{target,matches}')y on x->'id'=y->'id'where y is null or x-array['played_on','home_goals','away_goals','vir_brez_izida']<>y-array['played_on','home_goals','away_goals','vir_brez_izida']or exists(select 1 from private_historical_statistics.markers k where k.competition_id=1132 and k.source_report_id=x->>'zapisnik_id'and x<>y))and not exists(select 1 from jsonb_array_elements(prior#>'{target,rounds}')x left join jsonb_array_elements(after#>'{target,rounds}')y on x->'id'=y->'id'where y is null or x-array['played_on','deadline_at']<>y-array['played_on','deadline_at']),'only reviewed ordinary header/calendar fields changed; marker matches byte-exact');
 insert into private_baden_transition.versions(competition_id,manifest,manifest_sha256,bindings,opening_round_id,old_manifest_sha256,before_image_text,before_sha256,after_state,source_binding)values(1132,p->'manifest',h,p->'bindings',(p->>'openingRoundId')::bigint,'781b1784038fef6bdf223a8d127430d8ed37f76031126db62e3f1ef20d6e019e',before_text,before_sha,after,s);
 p:=private_baden_transition.readback(h);perform private_baden_transition.require_locks();perform private_baden_history.require((t::jsonb->>'currentFreshUntil')::timestamptz>clock_timestamp(),'source clock still valid after final independent readback');return p;
end$$;
